// WpdaWalker::run_with_consumer
// ══════════════════════════════════════════════════════════════════════════════

/// Stage 3.20 / L12 (Commit A, 2026-05-06): defensive Drop impl that
/// clears the mutable_token_source slot if the walker outlives the
/// caller's source. Prevents stale-pointer reuse in pathological cases
/// (e.g. walker stored in a long-lived consumer struct, source borrowed
/// per-parse).
impl<W: SemiringRef, E: WpdaEngine<W>> Drop for WpdaWalker<W, E> {
    fn drop(&mut self) {
        self.mutable_token_source = None;
    }
}

impl<W, E> WpdaWalker<W, E>
where
    W: SemiringRef
        + crate::automata::semiring::TropicalDeltaWeight
        + crate::automata::semiring::LexProvenance,
    E: WpdaEngine<W>,
{

    /// Env-aware run driver for codegen facades.
    ///
    /// Reads `PRATTAIL_MAX_STEPS` (fallback `default_max_steps`) and drives the
    /// pure single-engine parser to end of input. Returns the same
    /// `Result<(), WpdaMaxStepsExceeded>` as [`Self::run_to_end_of_input`], so
    /// codegen call sites can swap directly.
    ///
    /// The classic-reactive `PRATTAIL_TRACE` stderr trace was retired with the
    /// classic engine (CASE-2 single-engine re-platform, S4 2026-07-15); use the
    /// pure diagnostics `PRATTAIL_CGLL_PURE_TRACE` / `PRATTAIL_CANONICAL_GLL_STATS`.
    pub fn run_to_end_of_input_env_aware(
        &mut self,
        default_max_steps: usize,
        tokens: &dyn WpdaTokenSource,
    ) -> Result<(), WpdaMaxStepsExceeded>
    where
        W: 'static + std::fmt::Debug + IdempotentSemiring + StarSemiringRef,
    {
        let max_steps = std::env::var("PRATTAIL_MAX_STEPS")
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(default_max_steps);
        self.run_to_end_of_input(max_steps, tokens)
    }

    /// Env-aware demand-sensitive EOI driver for single-result facades.
    ///
    /// The `PRATTAIL_MAX_STEPS` counterpart of
    /// [`Self::run_to_end_of_input_until_accepting`]: stops as soon as a live EOI
    /// configuration can satisfy the requested root category. The classic-reactive
    /// `PRATTAIL_TRACE` / `PRATTAIL_TRACE_STRICT` trace was retired with the classic
    /// engine (CASE-2 single-engine re-platform, S4 2026-07-15).
    pub fn run_to_end_of_input_until_accepting_env_aware(
        &mut self,
        default_max_steps: usize,
        tokens: &dyn WpdaTokenSource,
    ) -> Result<(), WpdaMaxStepsExceeded>
    where
        W: 'static + std::fmt::Debug + IdempotentSemiring + StarSemiringRef,
    {
        let max_steps = std::env::var("PRATTAIL_MAX_STEPS")
            .ok()
            .and_then(|s| s.parse::<usize>().ok())
            .unwrap_or(default_max_steps);
        self.run_to_end_of_input_until_accepting(max_steps, tokens)
    }

}

